use std::collections::HashSet;

/// Removes duplicate values from the input vector `nums`.
/// 
/// The returned vector `res` has the following properties:
/// 1. No duplicate elements.
/// 2. The set of elements in `res` is exactly the set of elements in `nums`.
/// 3. The relative order of first occurrences in `nums` is preserved in `res`.
fn remove_duplicates(nums: Vec<i32>) -> Vec<i32> {
    let mut seen = HashSet::new();
    let mut res = Vec::new();

    for x in nums {
        // `HashSet::insert` returns true if `x` was not present in `seen`.
        if seen.insert(x) {
            res.push(x);
        }
    }

    res
}

fn main() {
    let v1 = vec![1, 2, 3, 2, 4, 1, 5];
    let v2 = remove_duplicates(v1.clone());
    println!("Input: {:?}\nOutput: {:?}", v1, v2);
    // Example output:
    // Input: [1, 2, 3, 2, 4, 1, 5]
    // Output: [1, 2, 3, 4, 5]

    let v3: Vec<i32> = vec![];
    let v4 = remove_duplicates(v3.clone());
    println!("Input: {:?}\nOutput: {:?}", v3, v4);
    // Input: []
    // Output: []
}